from datetime import datetimefrom db.models import MovieSession, Movie, CinemaHallfrom django.db.models.query import QuerySetdef create_movie_session(    movie_show_time: datetime,    movie_id: int,    cinema_hall_id: int) -> MovieSession:    movie = Movie.objects.get(id=movie_id)    hall = CinemaHall.objects.get(id=cinema_hall_id)    movie_session = MovieSession.objects.create(        show_time=movie_show_time,        movie=movie,        cinema_hall=hall,    )    return movie_sessiondef get_movies_sessions(session_date: datetime | None = None)\        -> QuerySet[MovieSession]:    queryset = MovieSession.objects.all()    if session_date:        queryset = queryset.filter(show_time__date=session_date)    return querysetdef get_movie_session_by_id(movie_session_id: int) -> MovieSession:    return MovieSession.objects.get(id=movie_session_id)def update_movie_session(    session_id: int,    show_time: datetime | None = None,    movie_id: int | None = None,    cinema_hall_id: int | None = None) -> MovieSession:    movie_session = MovieSession.objects.get(id=session_id)    if show_time is not None:        movie_session.show_time = show_time    if movie_id is not None:        movie_session.movie = Movie.objects.get(id=movie_id)    if cinema_hall_id is not None:        movie_session.cinema_hall = CinemaHall.objects.get(id=cinema_hall_id)    movie_session.save()    return movie_sessiondef delete_movie_session_by_id(session_id: int) -> None:    movie_session = MovieSession.objects.get(id=session_id)    movie_session.delete()